package net.civeira.phylax.feature.template.snippetversion.application.visibility;

import java.util.List;
import java.util.Optional;

import lombok.Builder;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.With;
import net.civeira.phylax.feature.template.snippet.domain.SnippetRef;

@Data
@Builder(toBuilder = true)
@With
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
public class SnippetVersionVisibilityFilter {

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated VisibilityFilterGenerator
   */
  private String search;

  /**
   * @autogenerated VisibilityFilterGenerator
   */
  private SnippetRef snippet;

  /**
   * @autogenerated VisibilityFilterGenerator
   */
  private String snippetTenantAccessible;

  /**
   * @autogenerated VisibilityFilterGenerator
   */
  private List<String> snippets;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated VisibilityFilterGenerator
   */
  private String uid;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated VisibilityFilterGenerator
   */
  private List<String> uids;

  /**
   * @autogenerated VisibilityFilterGenerator
   * @return
   */
  public Optional<String> getSearch() {
    return Optional.ofNullable(search);
  }

  /**
   * @autogenerated VisibilityFilterGenerator
   * @return
   */
  public Optional<SnippetRef> getSnippet() {
    return Optional.ofNullable(snippet);
  }

  /**
   * @autogenerated VisibilityFilterGenerator
   * @return
   */
  public Optional<String> getSnippetTenantAccessible() {
    return Optional.ofNullable(snippetTenantAccessible);
  }

  /**
   * @autogenerated VisibilityFilterGenerator
   * @return
   */
  public List<String> getSnippets() {
    return null == snippets ? List.of() : List.copyOf(snippets);
  }

  /**
   * @autogenerated VisibilityFilterGenerator
   * @return
   */
  public Optional<String> getUid() {
    return Optional.ofNullable(uid);
  }

  /**
   * @autogenerated VisibilityFilterGenerator
   * @return
   */
  public List<String> getUids() {
    return null == uids ? List.of() : List.copyOf(uids);
  }
}
